265	    /// Try push new query and check cancellation conditions
266	    bool tryPushQueryInteractively(const String & query, InterruptListener & interrupt_listener)
267	    {
268	        bool inserted = false;
269	
270	        while (!inserted)
271	        {
272	            inserted = queue.tryPush(query, 100);
273	
274	            if (shutdown)
275	            {
276	                /// An exception occurred in a worker
277	                return false;
278	            }
279	
280	            if (max_time > 0 && total_watch.elapsedSeconds() >= max_time)
281	            {
282	                std::cout << "Stopping launch of queries."
283	                          << " Requested time limit " << max_time << " seconds is exhausted.\n";
284	                return false;
285	            }
286	
287	            if (interrupt_listener.check())
288	            {
289	                std::cout << "Stopping launch of queries. SIGINT received." << std::endl;
290	                return false;
291	            }
292	
293	            if (delay > 0 && delay_watch.elapsedSeconds() > delay)
294	            {
295	                printNumberOfQueriesExecuted(queries_executed);
296	                cumulative ? report(comparison_info_total) : report(comparison_info_per_interval);
297	                delay_watch.restart();
298	            }
299	        }
300	
301	        return true;
302	    }
