304	    void runBenchmark()
305	    {
306	        pcg64 generator(randomSeed());
307	        std::uniform_int_distribution<size_t> distribution(0, queries.size() - 1);
308	
309	        try
310	        {
311	            for (size_t i = 0; i < concurrency; ++i)
312	            {
313	                EntryPtrs connection_entries;
314	                connection_entries.reserve(connections.size());
315	
316	                for (const auto & connection : connections)
317	                    connection_entries.emplace_back(std::make_shared<Entry>(
318	                            connection->get(ConnectionTimeouts::getTCPTimeoutsWithoutFailover(settings))));
319	
320	                pool.scheduleOrThrowOnError([this, connection_entries]() mutable { thread(connection_entries); });
321	            }
322	        }
323	        catch (...)
324	        {
325	            shutdown = true;
326	            pool.wait();
327	            throw;
328	        }
329	
330	        InterruptListener interrupt_listener;
331	        delay_watch.restart();
332	
333	        /// Push queries into queue
334	        for (size_t i = 0; !max_iterations || i < max_iterations; ++i)
335	        {
336	            size_t query_index = randomize ? distribution(generator) : i % queries.size();
337	
338	            if (!tryPushQueryInteractively(queries[query_index], interrupt_listener))
339	            {
340	                shutdown = true;
341	                break;
342	            }
343	        }
344	
345	        /// Now we don't block the Ctrl+C signal and second signal will terminate the program without waiting.
346	        interrupt_listener.unblock();
347	
348	        pool.wait();
349	        total_watch.stop();
350	
351	        if (!json_path.empty())
352	            reportJSON(comparison_info_total, json_path);
353	
354	        printNumberOfQueriesExecuted(queries_executed);
355	        report(comparison_info_total);
356	    }
