359	    void thread(EntryPtrs & connection_entries)
360	    {
361	        Query query;
362	
363	        /// Randomly choosing connection index
364	        pcg64 generator(randomSeed());
365	        std::uniform_int_distribution<size_t> distribution(0, connection_entries.size() - 1);
366	
367	        /// In these threads we do not accept INT signal.
368	        sigset_t sig_set;
369	        if (sigemptyset(&sig_set)
370	            || sigaddset(&sig_set, SIGINT)
371	            || pthread_sigmask(SIG_BLOCK, &sig_set, nullptr))
372	        {
373	            throwFromErrno("Cannot block signal.", ErrorCodes::CANNOT_BLOCK_SIGNAL);
374	        }
375	
376	        while (true)
377	        {
378	            bool extracted = false;
379	
380	            while (!extracted)
381	            {
382	                extracted = queue.tryPop(query, 100);
383	
384	                if (shutdown || (max_iterations && queries_executed == max_iterations))
385	                {
386	                    return;
387	                }
388	            }
389	
390	            const auto connection_index = distribution(generator);
391	            try
392	            {
393	                execute(connection_entries, query, connection_index);
394	            }
395	            catch (...)
396	            {
397	                std::lock_guard lock(mutex);
398	                std::cerr << "An error occurred while processing the query " << "'" << query << "'"
399	                          << ": " << getCurrentExceptionMessage(false) << std::endl;
400	                if (!continue_on_errors)
401	                {
402	                    shutdown = true;
403	                    throw;
404	                }
405	                else
406	                {
407	                    std::cerr << getCurrentExceptionMessage(print_stacktrace,
408	                        true /*check embedded stack trace*/) << std::endl;
409	
410	                    size_t info_index = round_robin ? 0 : connection_index;
411	                    comparison_info_per_interval[info_index]->errors++;
412	                    comparison_info_total[info_index]->errors++;
413	                }
414	            }
415	            // Count failed queries toward executed, so that we'd reach
416	            // max_iterations even if every run fails.
417	            ++queries_executed;
418	        }
419	    }
