421	    void execute(EntryPtrs & connection_entries, Query & query, size_t connection_index)
422	    {
423	        Stopwatch watch;
424	
425	        Connection & connection = **connection_entries[connection_index];
426	
427	        if (reconnect)
428	            connection.disconnect();
429	
430	        RemoteQueryExecutor executor(
431	            connection, query, {}, global_context, nullptr, Scalars(), Tables(), query_processing_stage);
432	        if (!query_id.empty())
433	            executor.setQueryId(query_id);
434	
435	        Progress progress;
436	        executor.setProgressCallback([&progress](const Progress & value) { progress.incrementPiecewiseAtomically(value); });
437	
438	        executor.sendQuery(ClientInfo::QueryKind::INITIAL_QUERY);
439	
440	        ProfileInfo info;
441	        while (Block block = executor.read())
442	            info.update(block);
443	
444	        executor.finish();
445	
446	        double seconds = watch.elapsedSeconds();
447	
448	        std::lock_guard lock(mutex);
449	
450	        size_t info_index = round_robin ? 0 : connection_index;
451	        comparison_info_per_interval[info_index]->add(seconds, progress.read_rows, progress.read_bytes, info.rows, info.bytes);
452	        comparison_info_total[info_index]->add(seconds, progress.read_rows, progress.read_bytes, info.rows, info.bytes);
453	        t_test.add(info_index, seconds);
454	    }
